  border-radius: 999px;
  font-weight: 600;
  font-size: .95rem;
  text-decoration: none;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform .12s ease, background .15s ease, color .15s ease, border-color .15s ease;
  font-family: inherit;
  line-height: 1.2;
}
.btn:active { transform: translateY(1px); }
.btn-primary { background: var(--accent); color: var(--accent-ink); }
.btn-primary:hover { background: var(--accent-2); }
.btn-ghost {
  background: transparent;
  color: var(--text);
  border-color: var(--border-strong);
}
.btn-ghost:hover { border-color: var(--text); }

.link-arrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--accent);
  text-decoration: none;
  font-weight: 600;
  border-bottom: 1px solid transparent;
}
.link-arrow:hover { border-bottom-color: var(--accent); }
.link-arrow-sm { font-size: .9rem; margin-top: 8px; }

/* ---------- Hero ---------- */
.hero {
  position: relative;
  overflow: hidden;
  padding: 64px 0 80px;
  border-bottom: 1px solid var(--border);
}
.hero::before {
  content: "";
  position: absolute; inset: 0;
  background:
    radial-gradient(700px 400px at 85% 30%, rgba(214,179,112,.18), transparent 60%),
    radial-gradient(500px 300px at 10% 80%, rgba(108,124,214,.10), transparent 60%);
  pointer-events: none;
}
.hero-inner {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 64px;
  align-items: center;
  position: relative;
}
.eyebrow {
  display: inline-block;
  margin: 0 0 14px;
  font-size: .78rem;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--accent);
  font-weight: 600;
}
.eyebrow-hot { color: var(--hot); }
h1#hero-title {
  font-size: clamp(2.4rem, 5vw, 4rem);
  line-height: 1.05;
  letter-spacing: -0.02em;
  margin: 0 0 18px;
  font-weight: 700;
}
.accent { color: var(--accent); font-style: italic; font-weight: 500; }

.lede {
  color: var(--text-muted);
  font-size: 1.1rem;
  max-width: 52ch;
  margin: 0 0 28px;
}
.hero-cta { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 32px; }
.hero-meta {
  list-style: none; padding: 0; margin: 0;
  display: flex; gap: 22px; flex-wrap: wrap;
  color: var(--text-dim);
  font-size: .9rem;
}
.hero-meta span { color: var(--accent); margin-right: 6px; }

.hero-visual {
  position: relative;
  aspect-ratio: 1 / 1;
  min-height: 420px;
}
.hero-card {
  position: absolute;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  background: var(--surface);
  box-shadow: var(--shadow-2);
  overflow: hidden;
}
.hero-card::after {
  content: "";
  position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 60%, rgba(0,0,0,.5) 100%);
}
.hero-card-1 {
  inset: 6% 22% 26% 6%;
  background:
    radial-gradient(circle at 30% 30%, #3a4250, #1a1f26 70%);
  transform: rotate(-3deg);
}
.hero-card-2 {
  inset: 18% 4% 14% 28%;
  background:
    linear-gradient(135deg, #2a2118, #4a3a22 60%, #6b5532);
  transform: rotate(2deg);
}
.hero-card-3 {
  inset: 38% 30% 6% 14%;
  background:
    linear-gradient(160deg, #1c2a2a, #2c4a48);
  transform: rotate(-1deg);
}
.hero-glow {
  position: absolute;
  width: 340px; height: 340px;
  right: -60px; bottom: -60px;
  background: radial-gradient(closest-side, rgba(214,179,112,.35), transparent 70%);
