+  --accent: #d6b370;       /* warm brass */
+  --accent-2: #e8c98a;
+  --accent-ink: #1a1206;
+
+  --hot: #ff7a59;
+  --good: #6cd6a3;
+  --danger: #ff6b6b;
+
+  --radius: 14px;
+  --radius-sm: 8px;
+  --radius-lg: 22px;
+
+  --shadow-1: 0 1px 2px rgba(0,0,0,.5), 0 8px 24px rgba(0,0,0,.35);
+  --shadow-2: 0 1px 2px rgba(0,0,0,.5), 0 18px 48px rgba(0,0,0,.55);
+
+  --container: 1240px;
+
+  --focus: 0 0 0 2px var(--bg), 0 0 0 4px var(--accent);
+}
+
+*, *::before, *::after { box-sizing: border-box; }
+
+html { -webkit-text-size-adjust: 100%; }
+
+body {
+  margin: 0;
+  font-family: "Inter", "Helvetica Neue", system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
+  font-size: 16px;
+  line-height: 1.55;
+  color: var(--text);
+  background: var(--bg);
+  background-image:
+    radial-gradient(1200px 700px at 80% -10%, rgba(214,179,112,.08), transparent 60%),
+    radial-gradient(900px 600px at -10% 10%, rgba(108, 124, 214, .06), transparent 60%);
+  background-attachment: fixed;
+  -webkit-font-smoothing: antialiased;
+}
+
+img, svg { display: block; max-width: 100%; }
+
+a { color: inherit; }
+a:focus-visible,
+button:focus-visible,
+input:focus-visible,
+[tabindex]:focus-visible {
+  outline: 2px solid var(--accent);
+  outline-offset: 2px;
+  border-radius: 4px;
+}
+
+/* Forced colors: ensure focus visible */
+@media (forced-colors: active) {
+  a:focus-visible, button:focus-visible, input:focus-visible {
+    outline: 2px solid CanvasText;
+  }
+}
+
+.visually-hidden {
+  position: absolute !important;
+  width: 1px; height: 1px;
+  padding: 0; margin: -1px;
+  overflow: hidden; clip: rect(0,0,0,0);
+  white-space: nowrap; border: 0;
+}
+
+.skip-link {
+  position: absolute;
+  left: 12px; top: -100px;
+  background: var(--accent);
+  color: var(--accent-ink);
+  padding: 10px 14px;
+  border-radius: var(--radius-sm);
+  font-weight: 600;
+  text-decoration: none;
+  z-index: 100;
+}
+.skip-link:focus { top: 12px; }
+
+.container {
+  width: 100%;
+  max-width: var(--container);
+  margin: 0 auto;
+  padding: 0 24px;
+}
+
+/* ---------- Header ---------- */
+.site-header {
+  position: sticky;
+  top: 0;
+  z-index: 50;
+  background: rgba(11,13,16,.78);
+  backdrop-filter: saturate(140%) blur(12px);
+  -webkit-backdrop-filter: saturate(140%) blur(12px);
+  border-bottom: 1px solid var(--border);
+}
+.header-inner {
+  display: grid;
+  grid-template-columns: auto 1fr auto;
+  align-items: center;
+  gap: 24px;
+  min-height: 72px;
+}
+.brand {
+  display: inline-flex;
+  align-items: center;
+  gap: 10px;
+  text-decoration: none;
+  color: var(--text);
+  font-weight: 700;
+  letter-spacing: .02em;
+}
+.brand-mark { color: var(--accent); }
+.brand-name { font-size: 1.15rem; }
+
+.primary-nav ul {
+  display: flex;
+  gap: 6px;
+  list-style: none;
+  margin: 0; padding: 0;
+  justify-content: center;
+}
+.primary-nav a {
+  display: inline-block;
+  padding: 10px 14px;
+  text-decoration: none;
+  color: var(--text-muted);
+  font-weight: 500;
+  border-radius: var(--radius-sm);
+}
+.primary-nav a:hover { color: var(--text); background: var(--surface); }
+
+.header-actions {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+}
+
+.search {
+  display: flex;
+  align-items: center;
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: 999px;
+  padding: 4px 4px 4px 14px;
+  width: 280px;
+  transition: border-color .15s ease;
+}
+.search:focus-within {
+  border-color: var(--accent);
+  outline: 2px solid var(--accent);
+  outline-offset: -2px;
+}
+.search input {
+  flex: 1;
+  border: 0;
+  background: transparent;
+  color: var(--text);
+  padding: 8px 4px;
+  font: inherit;
+  min-width: 0;
+}
+.search input::placeholder { color: var(--text-dim); }
+.search input:focus { outline: none; }
+.search button {
+  background: var(--accent);
+  color: var(--accent-ink);
+  border: 0;
+  width: 34px; height: 34px;
+  border-radius: 999px;
+  display: grid; place-items: center;
+  cursor: pointer;
+}
+.search button:hover { background: var(--accent-2); }
+
+.icon-btn {
+  position: relative;
+  background: transparent;
+  border: 1px solid transparent;
+  width: 42px; height: 42px;
+  border-radius: 50%;
+  color: var(--text);
+  cursor: pointer;
+  display: grid; place-items: center;
+}
+.icon-btn:hover { background: var(--surface); border-color: var(--border); }
+.cart-count {
+  position: absolute;
+  top: -2px; right: -2px;
+  background: var(--accent);
+  color: var(--accent-ink);
+  border-radius: 999px;
+  font-size: 11px;
+  font-weight: 700;
+  min-width: 18px; height: 18px;
+  padding: 0 5px;
+  display: grid; place-items: center;
+  border: 2px solid var(--bg);
+}
+
+/* ---------- Buttons ---------- */
+.btn {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 8px;
+  padding: 12px 20px;
+  border-radius: 999px;
+  font-weight: 600;
+  font-size: .95rem;
+  text-decoration: none;
+  border: 1px solid transparent;
+  cursor: pointer;
+  transition: transform .12s ease, background .15s ease, color .15s ease, border-color .15s ease;
+  font-family: inherit;
+  line-height: 1.2;
+}
+.btn:active { transform: translateY(1px); }
+.btn-primary { background: var(--accent); color: var(--accent-ink); }
+.btn-primary:hover { background: var(--accent-2); }
+.btn-ghost {
+  background: transparent;
+  color: var(--text);
+  border-color: var(--border-strong);
+}
+.btn-ghost:hover { border-color: var(--text); }
+
+.link-arrow {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  color: var(--accent);
+  text-decoration: none;
+  font-weight: 600;
+  border-bottom: 1px solid transparent;
+}
+.link-arrow:hover { border-bottom-color: var(--accent); }
+.link-arrow-sm { font-size: .9rem; margin-top: 8px; }
+
+/* ---------- Hero ---------- */
+.hero {
+  position: relative;
+  overflow: hidden;
+  padding: 64px 0 80px;
+  border-bottom: 1px solid var(--border);
+}
+.hero::before {
+  content: "";
+  position: absolute; inset: 0;
+  background:
+    radial-gradient(700px 400px at 85% 30%, rgba(214,179,112,.18), transparent 60%),
+    radial-gradient(500px 300px at 10% 80%, rgba(108,124,214,.10), transparent 60%);
+  pointer-events: none;
+}
+.hero-inner {
+  display: grid;
+  grid-template-columns: 1.1fr 1fr;
+  gap: 64px;
+  align-items: center;
+  position: relative;
+}
+.eyebrow {
+  display: inline-block;
+  margin: 0 0 14px;
+  font-size: .78rem;
+  letter-spacing: .18em;
+  text-transform: uppercase;
+  color: var(--accent);
+  font-weight: 600;
+}
+.eyebrow-hot { color: var(--hot); }
+h1#hero-title {
+  font-size: clamp(2.4rem, 5vw, 4rem);
+  line-height: 1.05;
+  letter-spacing: -0.02em;
+  margin: 0 0 18px;
+  font-weight: 700;
+}
+.accent { color: var(--accent); font-style: italic; font-weight: 500; }
+
+.lede {
+  color: var(--text-muted);
+  font-size: 1.1rem;
+  max-width: 52ch;
+  margin: 0 0 28px;
+}
+.hero-cta { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 32px; }
+.hero-meta {
+  list-style: none; padding: 0; margin: 0;
+  display: flex; gap: 22px; flex-wrap: wrap;
+  color: var(--text-dim);
+  font-size: .9rem;
+}
+.hero-meta span { color: var(--accent); margin-right: 6px; }
+
+.hero-visual {
+  position: relative;
+  aspect-ratio: 1 / 1;
+  min-height: 420px;
+}
+.hero-card {
+  position: absolute;
+  border-radius: var(--radius-lg);
+  border: 1px solid var(--border);
+  background: var(--surface);
+  box-shadow: var(--shadow-2);
+  overflow: hidden;
+}
+.hero-card::after {
+  content: "";
+  position: absolute; inset: 0;
+  background: linear-gradient(180deg, transparent 60%, rgba(0,0,0,.5) 100%);
+}
+.hero-card-1 {
+  inset: 6% 22% 26% 6%;
+  background:
+    radial-gradient(circle at 30% 30%, #3a4250, #1a1f26 70%);
+  transform: rotate(-3deg);
+}
+.hero-card-2 {
+  inset: 18% 4% 14% 28%;
+  background:
+    linear-gradient(135deg, #2a2118, #4a3a22 60%, #6b5532);
+  transform: rotate(2deg);
+}
+.hero-card-3 {
+  inset: 38% 30% 6% 14%;
+  background:
+    linear-gradient(160deg, #1c2a2a, #2c4a48);
+  transform: rotate(-1deg);
+}
+.hero-glow {
+  position: absolute;
+  width: 340px; height: 340px;
+  right: -60px; bottom: -60px;
+  background: radial-gradient(closest-side, rgba(214,179,112,.35), transparent 70%);
+  filter: blur(20px);
+  pointer-events: none;
+}
+
+/* ---------- Categories ---------- */
+.categories {
+  border-bottom: 1px solid var(--border);
+  background: var(--bg-2);
+}
+.category-list {
+  list-style: none;
+  margin: 0; padding: 18px 0;
+  display: flex;
+  gap: 8px;
+  overflow-x: auto;
+  scrollbar-width: thin;
+}
+.category-list a {
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  padding: 10px 16px;
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: 999px;
+  text-decoration: none;
+  color: var(--text);
+  font-weight: 500;
+  font-size: .92rem;
+  white-space: nowrap;
+}
+.category-list a:hover {
+  border-color: var(--accent);
+  color: var(--accent);
+}
+.cat-icon { color: var(--accent); }
+
+/* ---------- Sections ---------- */
+.section { padding: 80px 0; }
+.section-alt { background: var(--bg-2); border-block: 1px solid var(--border); }
+
+.section-head {
+  display: flex;
+  align-items: end;
+  justify-content: space-between;
+  gap: 24px;
+  margin-bottom: 36px;
+  flex-wrap: wrap;
+}
+.section-head h2 {
+  font-size: clamp(1.6rem, 3vw, 2.2rem);
+  margin: 0;
+  letter-spacing: -0.01em;
+}
+.section-sub {
+  color: var(--text-muted);
+  margin: 6px 0 0;
+}
+
+/* ---------- Product grid ---------- */
+.product-grid {
+  list-style: none;
+  margin: 0; padding: 0;
+  display: grid;
+  grid-template-columns: repeat(4, minmax(0, 1fr));
+  gap: 22px;
+}
+.product-card {
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  transition: transform .15s ease, border-color .15s ease, box-shadow .15s ease;
+}
+.product-card:hover {
+  transform: translateY(-3px);
+  border-color: var(--border-strong);
+  box-shadow: var(--shadow-1);
+}
+.product-media {
+  position: relative;
+  aspect-ratio: 4 / 5;
+  background: var(--bg-3);
+  overflow: hidden;
+}
+.product-media::after {
+  content: "";
+  position: absolute; inset: 0;
+  background: linear-gradient(180deg, transparent 65%, rgba(0,0,0,.45));
+}
+.product-badge {
+  position: absolute;
+  top: 12px; left: 12px;
+  background: var(--bg);
+  color: var(--accent);
+  font-size: .72rem;
+  font-weight: 700;
+  letter-spacing: .12em;
+  text-transform: uppercase;
+  padding: 6px 10px;
+  border-radius: 999px;
+  border: 1px solid var(--border-strong);
+  z-index: 1;
+}
+.product-badge.new { color: var(--good); }
+.product-badge.hot { color: var(--hot); }
+
+.fav-btn {
+  position: absolute;
+  top: 10px; right: 10px;
+  width: 36px; height: 36px;
+  border-radius: 50%;
+  background: rgba(11,13,16,.7);
+  border: 1px solid var(--border);
+  color: var(--text);
+  display: grid; place-items: center;
+  cursor: pointer;
+  z-index: 1;
+}
+.fav-btn[aria-pressed="true"] { color: var(--hot); border-color: var(--hot); }
+.fav-btn:hover { background: rgba(11,13,16,.9); }
+
+.product-body {
+  padding: 16px 16px 18px;
+  display: flex;
+  flex-direction: column;
+  gap: 6px;
+  flex: 1;
+}
+.product-cat {
+  font-size: .75rem;
+  color: var(--text-dim);
+  letter-spacing: .1em;
+  text-transform: uppercase;
+}
+.product-name {
+  font-size: 1rem;
+  font-weight: 600;
+  margin: 0;
+  line-height: 1.3;
+}
+.product-name a {
+  color: var(--text);
+  text-decoration: none;
+}
+.product-name a::after {
+  content: "";
+  position: absolute; inset: 0;
+}
+.product-card { position: relative; }
+
+.product-rating {
+  display: inline-flex; align-items: center; gap: 6px;
+  color: var(--text-dim);
+  font-size: .82rem;
+}
+.product-rating .stars { color: var(--accent); letter-spacing: 1px; }
+
+.product-foot {
+  margin-top: auto;
+  padding-top: 10px;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 12px;
+}
+.price { font-weight: 700; font-size: 1.05rem; }
+.price-old {
+  color: var(--text-dim);
+  text-decoration: line-through;
+  font-weight: 500;
+  font-size: .9rem;
+  margin-right: 6px;
+}
+.price-now { color: var(--text); }
+.price-now.sale { color: var(--accent-2); }
+
+.add-btn {
+  position: relative;
+  z-index: 2;
+  background: transparent;
+  color: var(--text);
+  border: 1px solid var(--border-strong);
+  padding: 8px 12px;
+  border-radius: 999px;
+  cursor: pointer;
+  font: inherit;
+  font-size: .85rem;
+  font-weight: 600;
+}
+.add-btn:hover { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
+
+/* Product image visuals (CSS art swatches) */
+.pm-1 { background: linear-gradient(135deg, #2b2218, #6b5532 70%, #8a6f3e); }
+.pm-2 { background: linear-gradient(160deg, #1c2230, #38445e); }
+.pm-3 { background: linear-gradient(135deg, #2c1c1c, #5a3030); }
+.pm-4 { background: linear-gradient(160deg, #16201c, #2c4a3e); }
+.pm-5 { background: linear-gradient(135deg, #1a1a1a, #3a3a3a); }
+.pm-6 { background: linear-gradient(160deg, #2a1a26, #4a2a40); }
+.pm-7 { background: linear-gradient(135deg, #1a2a2a, #2a4a4a); }
+.pm-8 { background: linear-gradient(160deg, #2a2218, #4a3822); }
+.pm-9 { background: linear-gradient(135deg, #20242e, #34384a); }
+.pm-10 { background: linear-gradient(160deg, #221c2c, #3a2e4e); }
+
+.product-media .glyph {
+  position: absolute; inset: 0;
+  display: grid; place-items: center;
+  font-size: 4rem;
+  color: rgba(255,255,255,.08);
+  font-weight: 700;
+}
+
+/* ---------- Deals ---------- */
+.countdown {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  background: var(--surface);
+  border: 1px solid var(--border-strong);
+  padding: 10px 14px;
+  border-radius: var(--radius-sm);
+  font-variant-numeric: tabular-nums;
+}
+.cd-block {
+  display: inline-flex;
+  flex-direction: column;
+  align-items: center;
+  min-width: 38px;
+}
+.cd-block > span:first-child {
+  font-size: 1.15rem;
+  font-weight: 700;
+  color: var(--text);
+  line-height: 1;
+}
+.cd-label {
+  font-size: .65rem;
+  letter-spacing: .12em;
+  text-transform: uppercase;
+  color: var(--text-dim);
+  margin-top: 4px;
+}
+.cd-sep { color: var(--text-dim); font-weight: 700; }
+
+.deals-grid {
+  list-style: none;
+  margin: 0; padding: 0;
+  display: grid;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  gap: 22px;
+}
+.deal-card {
+  position: relative;
+  display: grid;
+  grid-template-columns: 140px 1fr;
+  gap: 16px;
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  padding: 16px;
+  transition: transform .15s ease, border-color .15s ease;
+}
+.deal-card:hover { transform: translateY(-2px); border-color: var(--border-strong); }
+.deal-media {
+  aspect-ratio: 1;
+  border-radius: var(--radius-sm);
+  position: relative;
+  overflow: hidden;
+}
+.deal-discount {
+  position: absolute;
+  top: 8px; left: 8px;
+  background: var(--hot);
+  color: #1a0700;
+  font-weight: 700;
+  font-size: .75rem;
+  padding: 4px 8px;
+  border-radius: 999px;
+  z-index: 1;
+}
+.deal-body { display: flex; flex-direction: column; gap: 4px; }
+.deal-cat {
+  font-size: .72rem;
+  color: var(--text-dim);
+  letter-spacing: .1em;
+  text-transform: uppercase;
+}
+.deal-name {
+  font-size: 1rem;
+  font-weight: 600;
+  margin: 0;
+  line-height: 1.3;
+}
+.deal-name a { color: var(--text); text-decoration: none; }
+.deal-name a::after { content: ""; position: absolute; inset: 0; }
+.deal-price { margin-top: auto; padding-top: 8px; }
+.deal-stock {
+  font-size: .78rem;
+  color: var(--text-dim);
+  margin-top: 4px;
+}
+.deal-stock-bar {
+  display: block;
+  margin-top: 6px;
+  height: 4px;
+  background: var(--bg-3);
+  border-radius: 999px;
+  overflow: hidden;
+}
+.deal-stock-bar > span {
+  display: block;
+  height: 100%;
+  background: linear-gradient(90deg, var(--hot), var(--accent));
+}
+
+/* ---------- Editorial ---------- */
+.editorial-grid {
+  display: grid;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  gap: 22px;
+}
+.ed-card {
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  overflow: hidden;
+  position: relative;
+  transition: transform .15s ease, border-color .15s ease;
+}
+.ed-card:hover { transform: translateY(-2px); border-color: var(--border-strong); }
+.ed-feature { grid-column: span 3; }
+.ed-link {
+  display: grid;
+  text-decoration: none;
+  color: var(--text);
+  height: 100%;
+}
+.ed-feature .ed-link {
+  grid-template-columns: 1.1fr 1fr;
+}
+.ed-media {
+  position: relative;
+  aspect-ratio: 16 / 10;
+  background: var(--bg-3);
+}
+.ed-feature .ed-media { aspect-ratio: auto; min-height: 360px; }
+.ed-media::after {
+  content: "";
+  position: absolute; inset: 0;
+  background: linear-gradient(180deg, transparent 50%, rgba(0,0,0,.4));
+}
+.ed-media-1 { background: linear-gradient(135deg, #1a1410, #4a3322 70%, #6b4d2c); }
+.ed-media-2 { background: linear-gradient(160deg, #14181c, #2a3340); }
+.ed-media-3 { background: linear-gradient(135deg, #1a1c20, #2c2e3a 60%, #3a3f50); }
+.ed-media-4 { background: linear-gradient(160deg, #1c1a16, #3a3022); }
+
+.ed-body { padding: 22px; }
+.ed-feature .ed-body { padding: 36px; display: flex; flex-direction: column; justify-content: center; }
+.ed-meta {
+  font-size: .78rem;
+  color: var(--text-dim);
+  letter-spacing: .1em;
+  text-transform: uppercase;
+  margin: 0 0 10px;
+}
+.ed-card h3 {
+  font-size: 1.1rem;
+  margin: 0 0 8px;
+  line-height: 1.3;
+  font-weight: 600;
+  letter-spacing: -0.005em;
+}
+.ed-feature h3 {
+  font-size: clamp(1.4rem, 2.3vw, 1.8rem);
+  margin-bottom: 14px;
+}
+.ed-excerpt { color: var(--text-muted); margin: 0; }
+.ed-link:hover h3 { color: var(--accent); }
+
+/* ---------- Newsletter ---------- */
+.newsletter {
+  background:
+    linear-gradient(180deg, var(--bg-2), var(--bg)),
+    radial-gradient(circle at 80% 20%, rgba(214,179,112,.2), transparent 60%);
+  border-top: 1px solid var(--border);
+}
+.newsletter-inner {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 56px;
+  align-items: center;
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-lg);
+  padding: 48px;
+  position: relative;
+  overflow: hidden;
+}
