  ];

  const fmt = (n) => '$' + n.toFixed(0);

  function star(rating) {
    const full = Math.round(rating);
    return '★★★★★'.slice(0, full) + '☆☆☆☆☆'.slice(0, 5 - full);
  }

  function renderFeatured() {
    const grid = document.getElementById('featuredGrid');
    if (!grid) return;
    grid.innerHTML = featured.map((p) => `
      <li class="product-card">
        <div class="product-media ${p.img}">
          ${p.badge ? `<span class="product-badge ${p.badgeClass || ''}">${p.badge}</span>` : ''}
          <button type="button" class="fav-btn" aria-pressed="false" aria-label="Save ${escape(p.name)} to favorites" data-fav="${p.id}">
            <svg width="18" height="18" viewBox="0 0 24 24" aria-hidden="true" focusable="false">
              <path d="M12 21s-7.5-4.7-9.5-9.2C1 8 3.5 4 7.5 4c2 0 3.5 1.2 4.5 2.7C13 5.2 14.5 4 16.5 4 20.5 4 23 8 21.5 11.8 19.5 16.3 12 21 12 21z" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/>
            </svg>
          </button>
          <span class="glyph" aria-hidden="true">${p.glyph}</span>
        </div>
