          <span class="product-cat">${escape(p.cat)}</span>
          <h3 class="product-name"><a href="#product-${p.id}">${escape(p.name)}</a></h3>
          <span class="product-rating">
            <span class="stars" aria-hidden="true">${star(p.rating)}</span>
            <span class="visually-hidden">Rated ${p.rating} out of 5.</span>
            <span>${p.rating.toFixed(1)}</span>
          </span>
          <div class="product-foot">
            <span class="price"><span class="price-now">${fmt(p.price)}</span></span>
            <button type="button" class="add-btn" data-add="${p.id}" aria-label="Add ${escape(p.name)} to cart">Add</button>
          </div>
        </div>
      </li>
    `).join('');
  }

  function renderDeals() {
    const grid = document.getElementById('dealsGrid');
    if (!grid) return;
    grid.innerHTML = deals.map((p) => `
      <li class="deal-card">
        <div class="deal-media ${p.img}">
          <span class="deal-discount" aria-label="${p.off} percent off">−${p.off}%</span>
          <span class="glyph" aria-hidden="true" style="display:grid;place-items:center;height:100%;font-size:2.4rem;color:rgba(255,255,255,.10);font-weight:700;">${p.glyph}</span>
        </div>
        <div class="deal-body">
          <span class="deal-cat">${escape(p.cat)}</span>
          <h3 class="deal-name"><a href="#product-${p.id}">${escape(p.name)}</a></h3>
          <div class="deal-price">
            <span class="price">
              <span class="price-old" aria-label="Original price ${fmt(p.was)}">${fmt(p.was)}</span>
              <span class="price-now sale">${fmt(p.now)}</span>
            </span>
            <p class="deal-stock">
              ${Math.round(p.stock * 100)}% left in stock
              <span class="deal-stock-bar" aria-hidden="true"><span style="width:${Math.round(p.stock * 100)}%"></span></span>
            </p>
          </div>
        </div>
      </li>
    `).join('');
  }

  function escape(s) {
    return String(s).replace(/[&<>"']/g, (c) => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    }[c]));
  }

  // Cart
  let cartItems = 0;
  const cartCount = document.getElementById('cartCount');
  const cartBtn = document.getElementById('cartButton');
  function updateCart(n) {
    cartItems = Math.max(0, n);
    if (cartCount) cartCount.textContent = String(cartItems);
    if (cartBtn) cartBtn.setAttribute('aria-label', `Cart, ${cartItems} item${cartItems === 1 ? '' : 's'}`);
  }

  // Toast
  const toast = document.getElementById('toast');
  let toastTimer;
  function showToast(msg) {
    if (!toast) return;
    toast.textContent = msg;
    toast.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => toast.classList.remove('show'), 2400);
  }

  // Delegated clicks
  document.addEventListener('click', (e) => {
    const add = e.target.closest('[data-add]');
    if (add) {
      updateCart(cartItems + 1);
      const card = add.closest('.product-card');
      const name = card?.querySelector('.product-name')?.textContent || 'Item';
      showToast(`Added "${name}" to cart`);
      return;
    }
    const fav = e.target.closest('[data-fav]');
    if (fav) {
      const pressed = fav.getAttribute('aria-pressed') === 'true';
      fav.setAttribute('aria-pressed', String(!pressed));
      return;
    }
  });

  // Newsletter form
  const form = document.getElementById('newsletterForm');
  const email = document.getElementById('email');
  const emailError = document.getElementById('email-error');
  const formStatus = document.getElementById('formStatus');

  function setError(msg) {
    if (!email || !emailError) return;
    if (msg) {
      email.setAttribute('aria-invalid', 'true');
      emailError.textContent = msg;
      emailError.hidden = false;
    } else {
      email.removeAttribute('aria-invalid');
      emailError.textContent = '';
      emailError.hidden = true;
    }
  }

  if (form) {
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const value = (email.value || '').trim();
      if (!value) {
        setError('Please enter your email address.');
        email.focus();
        return;
      }
      const ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
      if (!ok) {
        setError('Please enter a valid email address (e.g., name@example.com).');
        email.focus();
        return;
      }
      setError(null);
      formStatus.textContent = `Thanks — we'll send the next Dispatch to ${value}.`;
      form.reset();
    });

    email.addEventListener('input', () => {
      if (email.getAttribute('aria-invalid') === 'true') setError(null);
    });
  }

  // Countdown — set to a fixed Friday-of-this-week-ish target so it always counts down
  function nextTarget() {
    const d = new Date();
    const target = new Date(d);
    // Aim for next Sunday 23:59:59
    const day = d.getDay();
    const daysUntilSunday = (7 - day) % 7 || 7;
    target.setDate(d.getDate() + daysUntilSunday);
    target.setHours(23, 59, 59, 0);
    return target;
  }
  const target = nextTarget();
  const cdDays = document.getElementById('cd-days');
  const cdHours = document.getElementById('cd-hours');
  const cdMins = document.getElementById('cd-mins');
  const cdSecs = document.getElementById('cd-secs');
  function pad(n) { return String(n).padStart(2, '0'); }
  function tick() {
    const now = new Date();
    let diff = Math.max(0, target - now);
    const days = Math.floor(diff / 86400000); diff -= days * 86400000;
    const hours = Math.floor(diff / 3600000); diff -= hours * 3600000;
    const mins = Math.floor(diff / 60000); diff -= mins * 60000;
    const secs = Math.floor(diff / 1000);
    if (cdDays) cdDays.textContent = pad(days);
    if (cdHours) cdHours.textContent = pad(hours);
    if (cdMins) cdMins.textContent = pad(mins);
    if (cdSecs) cdSecs.textContent = pad(secs);
  }
  tick();
  setInterval(tick, 1000);

  // Year
  const year = document.getElementById('year');
  if (year) year.textContent = new Date().getFullYear();

  // Init
  renderFeatured();
  renderDeals();
  updateCart(0);
})();
